98	function post(action, body) {
99	  return new Promise((resolve, reject) => {
100	    const token = fs.readFileSync(TOKEN_FILE, "utf8").trim();
101	    const data = JSON.stringify({ ...body, _caller: CALLER });
102	    const url = new URL(`/api/ash-hub-${action}`, STUB);
103	    const req = http.request(
