107	        let raw = "";
108	        res.on("data", (c) => (raw += c));
109	        res.on("end", () => {
110	          try {
111	            const json = JSON.parse(raw);
112	            if (json.ok) resolve(json.result);
113	            else reject(new Error(json.error || `stub said ${res.statusCode}`));
114	          } catch (error) {
115	            reject(error);
